import jax.numpy as jnp
import flax.linen as nn
from jax import random
import optax
from typing import Dict, Any, Sequence

class DSConvDilatedBlock(nn.Module):
    d_model: int; kernel_size: int = 7; dilation: int = 1; dropout_rate: float = 0.1
    @nn.compact
    def __call__(self, x, deterministic=True):
        h = nn.LayerNorm()(x)
        h = nn.Conv(features=self.d_model, kernel_size=(self.kernel_size,), feature_group_count=self.d_model, padding='SAME', kernel_dilation=(self.dilation,))(h)
        h = nn.gelu(h)
        h = nn.Conv(features=self.d_model, kernel_size=(1,))(h)
        h = nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)
        return x + h

class TransformerBlock(nn.Module):
    num_heads: int; embed_dim: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        x_norm = nn.LayerNorm()(x)
        x_attn = nn.SelfAttention(num_heads=self.num_heads)(x_norm)
        x = x + nn.Dropout(rate=self.dropout_rate)(x_attn, deterministic=deterministic)
        x_norm = nn.LayerNorm()(x)
        x_mlp = nn.Dense(features=self.embed_dim * 4)(x_norm)
        x_mlp = nn.relu(x_mlp)
        x_mlp = nn.Dense(features=self.embed_dim)(x_mlp)
        x = x + nn.Dropout(rate=self.dropout_rate)(x_mlp, deterministic=deterministic)
        return x

class TaskHead(nn.Module):
    d_output: int; task_type: str; dense_dim: int = 128; dropout_rate: float = 0.1; reg_head_dropout: float = 0.05; apply_regcal: bool = True
    @nn.compact
    def __call__(self, x, deterministic=True):
        head_dropout = self.reg_head_dropout if self.task_type == 'regression' else self.dropout_rate
        if self.task_type == 'regression' and self.apply_regcal:
            norm = jnp.linalg.norm(x, ord=2, axis=-1, keepdims=True)
            x = x / (norm + 1e-6)
        z = nn.Dense(self.dense_dim)(x); z = nn.gelu(z)
        z = nn.Dropout(rate=head_dropout)(z, deterministic=deterministic)
        logits = nn.Dense(self.d_output)(z)
        if self.task_type == 'regression': return logits.squeeze(-1)
        return logits

class FinalSynthesisModel(nn.Module):
    d_output: int; task_type: str; d_model: int = 256; kernel_size: int = 7; dilations: Sequence[int] = (1, 2, 4, 8, 16)
    dropout_rate: float = 0.1; motif_kernel_size: int = 5; motif_features: int = 256; transformer_heads: int = 4

    @nn.compact
    def __call__(self, x, deterministic=True):
        x = nn.Dense(features=self.d_model)(x)

        dsconv_features = x
        for dilation in self.dilations:
            dsconv_features = DSConvDilatedBlock(d_model=self.d_model, kernel_size=self.kernel_size, dilation=dilation, dropout_rate=self.dropout_rate)(dsconv_features, deterministic=deterministic)

        # Path 1: DSConv + Mean/Max Pooling
        main_agg = jnp.concatenate([jnp.mean(dsconv_features, axis=1), jnp.max(dsconv_features, axis=1)], axis=-1)

        # Path 2: Conv-Motif Detector
        motif_features = nn.gelu(nn.Conv(features=self.motif_features, kernel_size=(self.motif_kernel_size,))(x))
        motif_agg = jnp.max(motif_features, axis=1)

        # Path 3: Transformer (No Positional Encoding)
        transformer_output = dsconv_features
        for _ in range(2):
            transformer_output = TransformerBlock(num_heads=self.transformer_heads, embed_dim=self.d_model, dropout_rate=self.dropout_rate)(transformer_output, deterministic=deterministic)
        transformer_agg = jnp.mean(transformer_output, axis=1)

        combined = jnp.concatenate([main_agg, motif_agg, transformer_agg], axis=-1)
        fused = nn.LayerNorm()(combined)

        y = TaskHead(d_output=self.d_output, task_type=self.task_type)(fused, deterministic=deterministic)
        return y

class NetworkWrapper:
    def __init__(self, **kwargs): self.network = FinalSynthesisModel(**kwargs)
    def init(self, rng_key, dummy_input):
        p_key, d_key = random.split(rng_key)
        return self.network.init({'params': p_key, 'dropout': d_key}, dummy_input, deterministic=True)['params']
    def apply(self, params, x, deterministic=True, rng_key=None):
        rng = rng_key if rng_key is not None else random.PRNGKey(0)
        return self.network.apply({'params': params}, x, deterministic=deterministic, rngs={'dropout': rng})

def _define_hyperparameters(): return {'learning_rate': 0.001}
def create_network(hparams: Dict[str, Any]): return NetworkWrapper(d_output=hparams["d_output"], task_type=hparams["task_type"])
def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(optax.clip_by_global_norm(1.0), optax.adamw(learning_rate=learning_rate, weight_decay=0.012))
